test('module loads and exposes the API', () => {
  assert.equal(typeof C.conjugate, 'function');
  assert.equal(typeof C.isKnownIrregular, 'function');
  assert.equal(typeof C.listIrregulars, 'function');
  assert.deepEqual(C.PERSONS, ['je', 'tu', 'il', 'elle', 'nous', 'vous', 'ils']);
  assert.deepEqual(C.TENSES, ['present', 'passeCompose', 'imparfait', 'plusQueParfait', 'futur',
    'conditionnel', 'conditionnelPasse', 'subjonctif', 'imperatif']);
  assert.equal(globalThis.TEF_CONJ && typeof globalThis.TEF_CONJ.conjugate, 'function');
});

test('reference table covers 30 verbs', () => {
  assert.equal(Object.keys(REF).length, 30);
});

for (const [verb, ref] of Object.entries(REF)) {
  test(`full conjugation: ${verb}`, async (t) => {
    const r = C.conjugate(verb);
    assert.ok(r, `${verb} should conjugate`);
    assert.equal(r.group, ref.group, 'group');
    assert.equal(r.aux, ref.aux, 'aux');
    assert.equal(r.participle, ref.pp, 'participle');
    assert.equal(r.presentParticiple, ref.ppr, 'presentParticiple');
    assert.equal(r.pronominal, !!ref.pronominal, 'pronominal');
    assert.equal(r.impersonal, false, 'impersonal');
    for (const [k, name] of Object.entries(KEYS)) {
      await t.test(name, () => assert.deepEqual(r.tenses[name], R(ref[k])));
    }
  });
}

// ---------------------------------------------------------------------------
// Spot checks
// ---------------------------------------------------------------------------
const row = (verb, tense, i) => C.conjugate(verb).tenses[tense][i];

test('impersonal: falloir', () => {
  const r = C.conjugate('falloir');
  assert.equal(r.impersonal, true);
  assert.equal(r.aux, 'avoir');
  assert.equal(r.participle, 'fallu');
  assert.deepEqual(r.tenses.present, ['', '', 'il faut', '', '', '', '']);
  assert.equal(r.tenses.imparfait[2], 'il fallait');
  assert.equal(r.tenses.passeCompose[2], 'il a fallu');
  assert.equal(r.tenses.plusQueParfait[2], 'il avait fallu');
  assert.equal(r.tenses.futur[2], 'il faudra');
  assert.equal(r.tenses.conditionnel[2], 'il faudrait');
  assert.equal(r.tenses.conditionnelPasse[2], 'il aurait fallu');
  assert.deepEqual(r.tenses.subjonctif, ['', '', 'qu’il faille', '', '', '', '']);
  assert.deepEqual(r.tenses.imperatif, ['', '', '']);
  for (const t of C.TENSES.filter((x) => x !== 'imperatif')) {
    assert.equal(r.tenses[t].length, 7);
    r.tenses[t].forEach((x, i) => { if (i !== 2) assert.equal(x, '', `${t}[${i}]`); });
  }
});

test('impersonal: pleuvoir', () => {
  const r = C.conjugate('pleuvoir');
  assert.equal(r.impersonal, true);
  assert.equal(r.participle, 'plu');
  assert.equal(r.presentParticiple, 'pleuvant');
  assert.equal(r.tenses.present[2], 'il pleut');
  assert.equal(r.tenses.present[3], '');
  assert.equal(r.tenses.imparfait[2], 'il pleuvait');
  assert.equal(r.tenses.passeCompose[2], 'il a plu');
  assert.equal(r.tenses.futur[2], 'il pleuvra');
  assert.equal(r.tenses.conditionnel[2], 'il pleuvrait');
  assert.equal(r.tenses.subjonctif[2], 'qu’il pleuve');
  assert.deepEqual(r.tenses.imperatif, ['', '', '']);
});

test('elision before h muet vs h aspiré', () => {
  assert.equal(row('habiter', 'present', 0), 'j’habite');
  assert.equal(row('habiter', 'futur', 0), 'j’habiterai');
  assert.equal(row('habiter', 'subjonctif', 0), 'que j’habite');
  assert.equal(row('hésiter', 'present', 0), 'j’hésite');
  assert.equal(row('honorer', 'present', 0), 'j’honore');
  assert.equal(row('hurler', 'present', 0), 'je hurle');
  assert.equal(row('hausser', 'imparfait', 0), 'je haussais');
  assert.equal(row('hacher', 'present', 0), 'je hache');
  assert.equal(row('aimer', 'present', 0), 'j’aime');
  assert.equal(row('s’habiller', 'present', 0), 'je m’habille');
  assert.equal(row('s’habiller', 'present', 2), 'il s’habille');
});

test('haïr', () => {
  const r = C.conjugate('haïr');
  assert.equal(r.group, 2);
  assert.deepEqual(r.tenses.present, R('je hais|tu hais|il hait|elle hait|nous haïssons|vous haïssez|ils haïssent'));
  assert.equal(r.tenses.imparfait[0], 'je haïssais');
  assert.equal(r.tenses.futur[0], 'je haïrai');
  assert.equal(r.tenses.passeCompose[0], 'j’ai haï');
  assert.equal(r.tenses.subjonctif[0], 'que je haïsse');
  assert.deepEqual(r.tenses.imperatif, ['hais', 'haïssons', 'haïssez']);
  assert.equal(r.participle, 'haï');
  assert.equal(r.presentParticiple, 'haïssant');
});

test('s’asseoir', () => {
  for (const input of ['s’asseoir', "s'asseoir", 'S’asseoir ']) {
    const r = C.conjugate(input);
    assert.equal(r.infinitive, 's’asseoir');
    assert.equal(r.pronominal, true);
    assert.equal(r.aux, 'être');
    assert.equal(r.participle, 'assis');
    assert.deepEqual(r.tenses.present, R('je m’assieds|tu t’assieds|il s’assied|elle s’assied|nous nous asseyons|vous vous asseyez|ils s’asseyent'));
    assert.deepEqual(r.tenses.passeCompose, R('je me suis assis|tu t’es assis|il s’est assis|elle s’est assise|nous nous sommes assis|vous vous êtes assis|ils se sont assis'));
    assert.equal(r.tenses.futur[0], 'je m’assiérai');
    assert.equal(r.tenses.imparfait[4], 'nous nous asseyions');
    assert.equal(r.tenses.subjonctif[0], 'que je m’asseye');
    assert.deepEqual(r.tenses.imperatif, ['assieds-toi', 'asseyons-nous', 'asseyez-vous']);
  }
});

test('mourir', () => {
  const r = C.conjugate('mourir');
  assert.equal(r.aux, 'être');
  assert.equal(r.participle, 'mort');
  assert.deepEqual(r.tenses.present, R('je meurs|tu meurs|il meurt|elle meurt|nous mourons|vous mourez|ils meurent'));
  assert.deepEqual(r.tenses.passeCompose, R('je suis mort|tu es mort|il est mort|elle est morte|nous sommes morts|vous êtes morts|ils sont morts'));
  assert.equal(r.tenses.futur[0], 'je mourrai');
  assert.equal(r.tenses.conditionnel[6], 'ils mourraient');
  assert.equal(r.tenses.subjonctif[0], 'que je meure');
  assert.equal(r.tenses.subjonctif[4], 'que nous mourions');
});

test('prévoir futur is prévoirai (not prévrai)', () => {
  const r = C.conjugate('prévoir');
  assert.equal(r.tenses.futur[0], 'je prévoirai');
  assert.equal(r.tenses.conditionnel[4], 'nous prévoirions');
  assert.equal(r.tenses.present[4], 'nous prévoyons');
  assert.equal(r.participle, 'prévu');
  assert.equal(row('revoir', 'futur', 0), 'je reverrai');
  assert.equal(row('entrevoir', 'futur', 0), 'j’entreverrai');
});

test('se souvenir', () => {
  const r = C.conjugate('se souvenir');
  assert.equal(r.aux, 'être');
  assert.equal(r.participle, 'souvenu');
  assert.deepEqual(r.tenses.present, R('je me souviens|tu te souviens|il se souvient|elle se souvient|nous nous souvenons|vous vous souvenez|ils se souviennent'));
  assert.equal(r.tenses.passeCompose[3], 'elle s’est souvenue');
  assert.equal(r.tenses.passeCompose[5], 'vous vous êtes souvenus');
  assert.equal(r.tenses.futur[0], 'je me souviendrai');
  assert.equal(r.tenses.subjonctif[2], 'qu’il se souvienne');
  assert.deepEqual(r.tenses.imperatif, ['souviens-toi', 'souvenons-nous', 'souvenez-vous']);
});

test('-dire family: vous interdisez / contredisez but vous redites', () => {
  assert.equal(row('interdire', 'present', 5), 'vous interdisez');
  assert.equal(C.conjugate('interdire').tenses.imperatif[2], 'interdisez');
  assert.equal(row('contredire', 'present', 5), 'vous contredisez');
  assert.equal(row('prédire', 'present', 5), 'vous prédisez');
  assert.equal(row('redire', 'present', 5), 'vous redites');
  assert.equal(row('interdire', 'passeCompose', 0), 'j’ai interdit');
});

