test('2nd group and regular -re verbs', () => {
  for (const v of ['choisir', 'réussir', 'remplir', 'grandir', 'réfléchir', 'obéir', 'agir', 'établir', 'investir']) {
    const r = C.conjugate(v);
    const st = v.slice(0, -2);
    assert.equal(r.group, 2, v);
    assert.equal(r.tenses.present[4], 'nous ' + st + 'issons', v);
  }
  assert.equal(row('obéir', 'present', 0), 'j’obéis');
  for (const v of ['vendre', 'répondre', 'entendre', 'perdre', 'rendre', 'descendre', 'défendre']) {
    const r = C.conjugate(v);
    assert.equal(r.tenses.present[2], 'il ' + v.slice(0, -2), v);
    assert.equal(r.participle, v.slice(0, -2) + 'u', v);
  }
});

test('isKnownIrregular / listIrregulars', () => {
  assert.equal(C.isKnownIrregular('être'), true);
  assert.equal(C.isKnownIrregular('prendre'), true);
  assert.equal(C.isKnownIrregular('apprendre'), true);
  assert.equal(C.isKnownIrregular('parler'), false);
  assert.equal(C.isKnownIrregular('finir'), false);
  assert.equal(C.isKnownIrregular('xyz'), false);
  const list = C.listIrregulars();
  assert.ok(Array.isArray(list));
  for (const v of ['être', 'avoir', 'aller', 'faire', 'falloir', 'pleuvoir', 'asseoir', 'haïr']) assert.ok(list.includes(v), v);
});

test('null for invalid input', () => {
  for (const bad of [null, undefined, 42, {}, '', '   ', 'xyz', 'hello', 'parl', '123', 'se', 'chat', 'émouvoir', 'blorvoir', 'se falloir']) {
    assert.equal(C.conjugate(bad), null, String(bad));
  }
});

test('input normalisation', () => {
  assert.equal(C.conjugate('  Parler ').infinitive, 'parler');
  assert.equal(C.conjugate("s'appeler").infinitive, 's’appeler');
  assert.equal(C.conjugate("s'appeler").tenses.present[1], 'tu t’appelles');
  assert.equal(C.conjugate('se promener').tenses.passeCompose[3], 'elle s’est promenée');
});
